extension SeatRole {
    /// The roles whose work a seat of this role does (roles.json `acts_as`).
    public var actsAs: [SeatRole] {
        switch self {
        case .builder: return [.builder]
        case .reviewer: return [.reviewer]
        case .planner: return [.planner]
        case .orchestrator: return [.orchestrator]
        case .general: return [.builder, .reviewer, .planner, .orchestrator]
        }
    }

    /// Whether a seat of this role gets a role file (roles.json `role_file`).
    public var hasRoleFile: Bool {
        switch self {
        case .builder: return true
        case .reviewer: return true
        case .planner: return true
        case .orchestrator: return true
        case .general: return false
        }
    }

    /// Whether a seat of this role does the work of `role`.
    public func actsAs(_ role: SeatRole) -> Bool { actsAs.contains(role) }
}
